<form method="post" action="{{ $doctor ? route('doctors.update',$doctor) : route('doctors.store') }}" class="form-stack">@csrf @if($doctor)@method('PUT')@endif<div class="form-grid"><x-clinic-field name="name" label="Full name" :value="$doctor?->name" required/><x-clinic-field name="email" label="Email" type="email" :value="$doctor?->email" required/><x-clinic-field name="specialization" label="Specialization" :value="$doctor?->specialization" required/><x-clinic-field name="consultation_fee" label="Consultation fee" type="number" :value="$doctor?->consultation_fee ?? 0" min="0" max="999999" step="0.01" required/><x-clinic-field name="starts_at" label="Starts at" type="time" :value="substr($doctor?->starts_at ?? '09:00',0,5)" required/><x-clinic-field name="ends_at" label="Ends at" type="time" :value="substr($doctor?->ends_at ?? '17:00',0,5)" required/><label class="field"><span>{{ __('Visit length') }}</span><select name="slot_minutes">@foreach([15,20,30,60] as $n)<option value="{{ $n }}" @selected(($doctor?->slot_minutes ?? 30)==$n)>{{ $n }} {{ __('minutes') }}</option>@endforeach</select></label><label class="field"><span>{{ __('Status') }}</span><select name="status">@foreach(['active','inactive'] as $s)<option value="{{ $s }}" @selected($doctor?->status===$s)>{{ __(ucfirst($s)) }}</option>@endforeach</select></label></div><fieldset><legend>{{ __('Working days') }}</legend><div class="days">@foreach(['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'] as $i=>$day)<label><input type="checkbox" name="working_days[]" value="{{ $i }}" @checked(in_array($i,$doctor?->working_days ?? [0,1,2,3,4]))>{{ __($day) }}</label>@endforeach</div></fieldset><button class="button">{{ __('Save doctor') }}</button></form>
